alter table ingest.raw_rows add column normalized_content jsonb;
alter table ingest.raw_rows add column validation_errors jsonb not null default '[]';
create policy backend_contracts on ingest.source_contracts for all to service_role using (true) with check (true);
create or replace function analytics.promote_version(p_version uuid) returns void language plpgsql security invoker set search_path='' as $$
declare ws uuid; sources integer; state text; begin
select workspace_id,status into strict ws,state from analytics.dataset_versions where id=p_version for update;
if state<>'candidate' then raise exception 'Apenas versão candidata pode ser promovida'; end if;
select count(*) into sources from analytics.version_sources vs join ingest.source_files f on f.id=vs.file_id where vs.version_id=p_version and f.status='verified';
if sources<>5 then raise exception 'São necessárias cinco fontes verificadas'; end if;
insert into core.accounts(workspace_id,version_id,source_row_id,account_id,account_name,industry,country,referral_source,plan_tier,seats,is_trial,churn_flag,signup_date) select ws,p_version,r.id,nullif(r.normalized_content->>'account_id','')::text,nullif(r.normalized_content->>'account_name','')::text,nullif(r.normalized_content->>'industry','')::text,nullif(r.normalized_content->>'country','')::text,nullif(r.normalized_content->>'referral_source','')::text,nullif(r.normalized_content->>'plan_tier','')::text,nullif(r.normalized_content->>'seats','')::integer,nullif(r.normalized_content->>'is_trial','')::boolean,nullif(r.normalized_content->>'churn_flag','')::boolean,nullif(r.normalized_content->>'signup_date','')::date from ingest.raw_rows r join analytics.version_sources vs on vs.file_id=r.file_id and vs.version_id=p_version where vs.source_type='accounts' on conflict do nothing;
if (select count(*) from core.accounts where version_id=p_version)<>(select f.expected_rows from analytics.version_sources vs join ingest.source_files f on f.id=vs.file_id where vs.version_id=p_version and vs.source_type='accounts') then raise exception 'Contagem canônica divergente: accounts'; end if;
insert into core.subscriptions(workspace_id,version_id,source_row_id,subscription_id,account_id,plan_tier,billing_frequency,seats,mrr_amount,arr_amount,is_trial,upgrade_flag,downgrade_flag,churn_flag,auto_renew_flag,start_date,end_date) select ws,p_version,r.id,nullif(r.normalized_content->>'subscription_id','')::text,nullif(r.normalized_content->>'account_id','')::text,nullif(r.normalized_content->>'plan_tier','')::text,nullif(r.normalized_content->>'billing_frequency','')::text,nullif(r.normalized_content->>'seats','')::integer,nullif(r.normalized_content->>'mrr_amount','')::numeric,nullif(r.normalized_content->>'arr_amount','')::numeric,nullif(r.normalized_content->>'is_trial','')::boolean,nullif(r.normalized_content->>'upgrade_flag','')::boolean,nullif(r.normalized_content->>'downgrade_flag','')::boolean,nullif(r.normalized_content->>'churn_flag','')::boolean,nullif(r.normalized_content->>'auto_renew_flag','')::boolean,nullif(r.normalized_content->>'start_date','')::date,nullif(r.normalized_content->>'end_date','')::date from ingest.raw_rows r join analytics.version_sources vs on vs.file_id=r.file_id and vs.version_id=p_version where vs.source_type='subscriptions' on conflict do nothing;
if (select count(*) from core.subscriptions where version_id=p_version)<>(select f.expected_rows from analytics.version_sources vs join ingest.source_files f on f.id=vs.file_id where vs.version_id=p_version and vs.source_type='subscriptions') then raise exception 'Contagem canônica divergente: subscriptions'; end if;
insert into core.feature_usage(workspace_id,version_id,source_row_id,usage_id,subscription_id,feature_name,usage_count,usage_duration_secs,error_count,is_beta_feature,usage_date) select ws,p_version,r.id,nullif(r.normalized_content->>'usage_id','')::text,nullif(r.normalized_content->>'subscription_id','')::text,nullif(r.normalized_content->>'feature_name','')::text,nullif(r.normalized_content->>'usage_count','')::integer,nullif(r.normalized_content->>'usage_duration_secs','')::integer,nullif(r.normalized_content->>'error_count','')::integer,nullif(r.normalized_content->>'is_beta_feature','')::boolean,nullif(r.normalized_content->>'usage_date','')::date from ingest.raw_rows r join analytics.version_sources vs on vs.file_id=r.file_id and vs.version_id=p_version where vs.source_type='usage' on conflict do nothing;
if (select count(*) from core.feature_usage where version_id=p_version)<>(select f.expected_rows from analytics.version_sources vs join ingest.source_files f on f.id=vs.file_id where vs.version_id=p_version and vs.source_type='usage') then raise exception 'Contagem canônica divergente: usage'; end if;
insert into core.support_tickets(workspace_id,version_id,source_row_id,ticket_id,account_id,priority,first_response_time_minutes,resolution_time_hours,satisfaction_score,escalation_flag,submitted_at,closed_at) select ws,p_version,r.id,nullif(r.normalized_content->>'ticket_id','')::text,nullif(r.normalized_content->>'account_id','')::text,nullif(r.normalized_content->>'priority','')::text,nullif(r.normalized_content->>'first_response_time_minutes','')::integer,nullif(r.normalized_content->>'resolution_time_hours','')::numeric,nullif(r.normalized_content->>'satisfaction_score','')::numeric,nullif(r.normalized_content->>'escalation_flag','')::boolean,nullif(r.normalized_content->>'submitted_at','')::timestamp without time zone,nullif(r.normalized_content->>'closed_at','')::timestamp without time zone from ingest.raw_rows r join analytics.version_sources vs on vs.file_id=r.file_id and vs.version_id=p_version where vs.source_type='support' on conflict do nothing;
if (select count(*) from core.support_tickets where version_id=p_version)<>(select f.expected_rows from analytics.version_sources vs join ingest.source_files f on f.id=vs.file_id where vs.version_id=p_version and vs.source_type='support') then raise exception 'Contagem canônica divergente: support'; end if;
insert into core.churn_events(workspace_id,version_id,source_row_id,churn_event_id,account_id,reason_code,feedback_text,refund_amount_usd,preceding_upgrade_flag,preceding_downgrade_flag,is_reactivation,churn_date) select ws,p_version,r.id,nullif(r.normalized_content->>'churn_event_id','')::text,nullif(r.normalized_content->>'account_id','')::text,nullif(r.normalized_content->>'reason_code','')::text,nullif(r.normalized_content->>'feedback_text','')::text,nullif(r.normalized_content->>'refund_amount_usd','')::numeric,nullif(r.normalized_content->>'preceding_upgrade_flag','')::boolean,nullif(r.normalized_content->>'preceding_downgrade_flag','')::boolean,nullif(r.normalized_content->>'is_reactivation','')::boolean,nullif(r.normalized_content->>'churn_date','')::date from ingest.raw_rows r join analytics.version_sources vs on vs.file_id=r.file_id and vs.version_id=p_version where vs.source_type='churn' on conflict do nothing;
if (select count(*) from core.churn_events where version_id=p_version)<>(select f.expected_rows from analytics.version_sources vs join ingest.source_files f on f.id=vs.file_id where vs.version_id=p_version and vs.source_type='churn') then raise exception 'Contagem canônica divergente: churn'; end if;
end
$$;
